//! The 64 pipelines (57 compute kernels, 7 draws), built lazily from the committed shader outputs.
//!
//! `shaders/entries.rs` (generated by `cargo xtask shaders`) lists every entry point with its stage, workgroup size and
//! the backend bytes: MSL on macOS, DXIL on Windows. Compute pipelines are keyed by (module, entry, `out0` format) because
//! the storage texture format is part of the bind group layout; draws by vertex/fragment pair, target format, blend and
//! primitive. Entry names are the Slang names (`colorChain`, `compositeVertex`).

mod passthrough;
pub(crate) mod warm;
pub use warm::prewarm_done_at;

use crate::gpu::{Gpu, GpuError, lock};
use crate::layout::{LayoutKind, PixelFormat};
use std::sync::Arc;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ShaderStage {
    Compute,
    Vertex,
    Fragment,
}

/// One entry point of the compiled shader set.
pub struct ShaderEntry {
    pub module: &'static str,
    pub name: &'static str,
    pub stage: ShaderStage,
    pub workgroup: (u32, u32, u32),
    /// `out0` is read-write (the module defines `SQ_OUT_READ`).
    pub out_read: bool,
    /// Sizes of the constant blocks b0 and b1 in bytes (0 = none).
    pub cbuffers: [u32; 2],
    /// The MSL source of the whole module.
    #[cfg(target_os = "macos")]
    pub msl: &'static str,
    /// The DXIL of this entry point.
    #[cfg(windows)]
    pub dxil: &'static [u8],
    /// The SPIR-V of this entry point (little-endian words).
    #[cfg(not(any(target_os = "macos", windows)))]
    pub spirv: &'static [u8],
}

include!("../../shaders/entries.rs");

/// The entry `name` of `module`.
pub fn find(module: &str, name: &str) -> Option<&'static ShaderEntry> {
    ENTRIES.iter().find(|e| e.module == module && e.name == name)
}

/// Bind group layout and pipeline layout of one [`LayoutKind`].
pub struct Layout {
    pub(crate) kind: LayoutKind,
    pub(crate) group: wgpu::BindGroupLayout,
    pub(crate) pipeline: wgpu::PipelineLayout,
}

pub struct ComputePipeline {
    pub(crate) raw: wgpu::ComputePipeline,
    pub(crate) layout: Arc<Layout>,
    /// Format of `out0` the pipeline was built for.
    pub(crate) out_format: PixelFormat,
    /// `Module.entry`, the name of a pass in the GPU timing report.
    pub(crate) label: String,
}

pub struct RenderPipeline {
    pub(crate) raw: wgpu::RenderPipeline,
    pub(crate) layout: Arc<Layout>,
    /// `Module.fragment`, the name of a pass in the GPU timing report.
    pub(crate) label: String,
}

/// Fixed-function blending of a draw's output onto its target (premultiplied colors).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Blend {
    /// The fragment's value replaces the target pixel.
    Replace,
    /// `out = src + dst * (1 - src.a)`.
    PremultipliedOver,
    /// `out = src * src.a + dst * (1 - src.a)`, alpha `a + dst.a * (1 - a)`: straight-alpha color (the draw UI).
    StraightOver,
    /// `out = src + dst`.
    Additive,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Primitive {
    Triangles,
    TriangleStrip,
}

/// A draw: vertex and fragment entry of one module, the target format and the fixed-function state.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct RenderKey {
    pub module: &'static str,
    pub vertex: &'static str,
    pub fragment: &'static str,
    pub format: PixelFormat,
    pub blend: Blend,
    pub primitive: Primitive,
}

fn blend_state(blend: Blend) -> Option<wgpu::BlendState> {
    let component = |dst| wgpu::BlendComponent {
        src_factor: wgpu::BlendFactor::One,
        dst_factor: dst,
        operation: wgpu::BlendOperation::Add,
    };
    match blend {
        Blend::Replace => None,
        Blend::PremultipliedOver => Some(wgpu::BlendState {
            color: component(wgpu::BlendFactor::OneMinusSrcAlpha),
            alpha: component(wgpu::BlendFactor::OneMinusSrcAlpha),
        }),
        Blend::StraightOver => Some(wgpu::BlendState {
            color: wgpu::BlendComponent {
                src_factor: wgpu::BlendFactor::SrcAlpha,
                dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
                operation: wgpu::BlendOperation::Add,
            },
            alpha: component(wgpu::BlendFactor::OneMinusSrcAlpha),
        }),
        Blend::Additive => Some(wgpu::BlendState {
            color: component(wgpu::BlendFactor::One),
            alpha: component(wgpu::BlendFactor::One),
        }),
    }
}

/// Held while one thread compiles a pipeline; dropping it wakes the threads waiting for that pipeline.
pub(crate) struct BuildClaim<'a> {
    gpu: &'a Gpu,
    id: String,
}

impl Drop for BuildClaim<'_> {
    fn drop(&mut self) {
        lock(&self.gpu.building.0).remove(&self.id);
        self.gpu.building.1.notify_all();
    }
}

impl Gpu {
    /// `Some` when nobody else builds `id` (the caller builds it); otherwise waits until the other build ends and gives `None`
    /// (the caller looks in the cache again).
    fn claim_build(&self, id: String) -> Option<BuildClaim<'_>> {
        let mut set = lock(&self.building.0);
        if set.insert(id.clone()) {
            return Some(BuildClaim { gpu: self, id });
        }
        while set.contains(&id) {
            set = self.building.1.wait(set).unwrap_or_else(|e| e.into_inner());
        }
        None
    }

    /// The compute pipeline of `module.entry` writing `out0` of `out` (use `Rgba16Float` when the pass writes no texture).
    pub fn compute_pipeline(
        &self,
        module: &'static str,
        entry: &'static str,
        out: PixelFormat,
    ) -> Result<Arc<ComputePipeline>, GpuError> {
        // The lock is held only for lookup and insert, never across the compile: the start-up warm-up thread and the render
        // thread build different pipelines at the same time.
        let id = format!("c {module}.{entry} {out:?}");
        let _claim = loop {
            if let Some(p) = lock(&self.compute).get(&(module, entry, out)) {
                return Ok(Arc::clone(p));
            }
            // One build per pipeline: a thread that needs what the warm-up is compiling waits for it instead of compiling twice.
            if let Some(claim) = self.claim_build(id.clone()) {
                break claim;
            }
        };
        if let Some(p) = lock(&self.compute).get(&(module, entry, out)) {
            return Ok(Arc::clone(p));
        }
        let shader =
            find(module, entry).filter(|e| e.stage == ShaderStage::Compute).ok_or_else(|| unknown(module, entry))?;
        if !out.is_storage() {
            return Err(GpuError::Pipeline(format!("{out:?} cannot be a storage texture")));
        }
        let kind = if shader.out_read { LayoutKind::ComputeInPlace } else { LayoutKind::Compute };
        let _create = sq_os::trace::span_args("gpu", "pipeline create", || format!("compute {module}.{entry}"));
        let layout = self.layout(kind, out);
        let module_handle = self.shader_module(shader)?;
        let raw = self.scoped(|| {
            self.device().create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
                label: Some(entry),
                layout: Some(&layout.pipeline),
                module: &module_handle,
                entry_point: Some(entry),
                compilation_options: Default::default(),
                cache: self.pipeline_cache.as_ref().map(|(c, _)| c),
            })
        })?;
        let pipeline = Arc::new(ComputePipeline { raw, layout, out_format: out, label: format!("{module}.{entry}") });
        Ok(Arc::clone(lock(&self.compute).entry((module, entry, out)).or_insert(pipeline)))
    }

    /// The draw pipeline for `key`.
    pub fn render_pipeline(&self, key: RenderKey) -> Result<Arc<RenderPipeline>, GpuError> {
        let id = format!("r {key:?}");
        let _claim = loop {
            if let Some(p) = lock(&self.render).get(&key) {
                return Ok(Arc::clone(p));
            }
            if let Some(claim) = self.claim_build(id.clone()) {
                break claim;
            }
        };
        if let Some(p) = lock(&self.render).get(&key) {
            return Ok(Arc::clone(p));
        }
        let vertex = find(key.module, key.vertex)
            .filter(|e| e.stage == ShaderStage::Vertex)
            .ok_or_else(|| unknown(key.module, key.vertex))?;
        let fragment = find(key.module, key.fragment)
            .filter(|e| e.stage == ShaderStage::Fragment)
            .ok_or_else(|| unknown(key.module, key.fragment))?;
        if !key.format.is_renderable() {
            return Err(GpuError::Pipeline(format!("{:?} cannot be a render target", key.format)));
        }
        let kind = if key.module == "DrawQuads" { LayoutKind::DrawQuads } else { LayoutKind::Render };
        let _create =
            sq_os::trace::span_args("gpu", "pipeline create", || format!("render {}.{}", key.module, key.fragment));
        let layout = self.layout(kind, PixelFormat::Rgba16Float);
        let (vertex_module, fragment_module) = (self.shader_module(vertex)?, self.shader_module(fragment)?);
        let topology = match key.primitive {
            Primitive::Triangles => wgpu::PrimitiveTopology::TriangleList,
            Primitive::TriangleStrip => wgpu::PrimitiveTopology::TriangleStrip,
        };
        let raw = self.scoped(|| {
            self.device().create_render_pipeline(&wgpu::RenderPipelineDescriptor {
                label: Some(key.fragment),
                layout: Some(&layout.pipeline),
                vertex: wgpu::VertexState {
                    module: &vertex_module,
                    entry_point: Some(key.vertex),
                    compilation_options: Default::default(),
                    buffers: &[],
                },
                primitive: wgpu::PrimitiveState { topology, ..Default::default() },
                depth_stencil: None,
                multisample: Default::default(),
                fragment: Some(wgpu::FragmentState {
                    module: &fragment_module,
                    entry_point: Some(key.fragment),
                    compilation_options: Default::default(),
                    targets: &[Some(wgpu::ColorTargetState {
                        format: key.format.wgpu(),
                        blend: blend_state(key.blend),
                        write_mask: wgpu::ColorWrites::ALL,
                    })],
                }),
                multiview_mask: None,
                cache: self.pipeline_cache.as_ref().map(|(c, _)| c),
            })
        })?;
        let pipeline = Arc::new(RenderPipeline { raw, layout, label: format!("{}.{}", key.module, key.fragment) });
        Ok(Arc::clone(lock(&self.render).entry(key).or_insert(pipeline)))
    }
}

fn unknown(module: &str, entry: &str) -> GpuError {
    GpuError::Pipeline(format!("no entry point {module}.{entry} of that stage"))
}
